const help='A fictional neighbor is making a flood-history display for the town’s market. These source cards are here for us to inspect, not hidden evidence. Card B was made by looking at photograph PH8646, Card A: the arrow means “was made using”. The note can be useful without adding a separate historical observation. Card C is a modern date summary; its underlying records are not given here. Unknown independence is not proven dependence, and different publishers do not prove independence. There is no positive independent-witness example in this packet. Choosing from these answers and reading the feedback is practice; it is not historical research or reading done on your own.';
export const sourceTrailCases=rows.map(([id,title,prompt,choices,answerId,feedback])=>({version:1,id,title,prompt,choices:[...choices.map(([id,label])=>({id,label})),{id:'unsure',label:'Not sure yet'}],answerId,feedback,help,cards:structuredClone(cards),photo:structuredClone(photo),pictureVersion:1}));
export const sourceTrailSource=id=>{const s=sourceTrailCases.find(s=>s.id===id);return s?structuredClone(s):null;};
